function PathIcon({ path, props, viewBox }: { path: string; props: IconProps; viewBox?: string }) {
  return (
    <svg {...base(props, viewBox)}>
      <g>
        <path fill="currentColor" d={path} />
      </g>
    </svg>
  )
}

