export function VerifiedBadge({ type }: { type: 'blue' | 'gold' | 'gray' }) {
  const uniqueId = useId().replace(/:/g, '')
  if (type !== 'gold') {
    return (
      <svg className="verifiedBadge" viewBox="0 0 22 22" aria-label="认证账号" role="img">
        <g>
          <path fill={type === 'blue' ? '#1d9bf0' : '#82909a'} d={paths.verified} />
        </g>
      </svg>
    )
  }
  const outer = `${uniqueId}-gold-a`
  const inner = `${uniqueId}-gold-b`
  return (
    <svg className="verifiedBadge" viewBox="0 0 22 22" aria-label="认证账号" role="img">
      <defs>
        <linearGradient gradientUnits="userSpaceOnUse" id={outer} x1="4.411" x2="18.083" y1="2.495" y2="21.508">
          <stop offset="0" stopColor="#f4e72a" />
          <stop offset=".539" stopColor="#cd8105" />
          <stop offset=".68" stopColor="#cb7b00" />
          <stop offset="1" stopColor="#f4ec26" />
          <stop offset="1" stopColor="#f4e72a" />
        </linearGradient>
        <linearGradient gradientUnits="userSpaceOnUse" id={inner} x1="5.355" x2="16.361" y1="3.395" y2="19.133">
          <stop offset="0" stopColor="#f9e87f" />
          <stop offset=".406" stopColor="#e2b719" />
          <stop offset=".989" stopColor="#e2b719" />
        </linearGradient>
      </defs>
      <g clipRule="evenodd" fillRule="evenodd">
        <path d={paths.goldOuter} fill={`url(#${outer})`} />
        <path d={paths.goldInner} fill={`url(#${inner})`} />
        <path d={paths.goldEdge} fill="#d18800" />
      </g>
    </svg>
  )
}

